package worker

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

const resultsPath = "out/results.json"

type Result struct {
	Job   string
	Value int
}

// RunAll processes jobs with two workers, then appends all results to out/results.json.
// Each worker fills only its own slots of results; the file has a single writer.
func RunAll(jobs []string) error {
	results := make([]Result, len(jobs))
	var wg sync.WaitGroup
	for w := 0; w < 2; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := w; i < len(jobs); i += 2 {
				results[i] = Result{Job: jobs[i], Value: len(jobs[i])}
			}
		}(w)
	}
	wg.Wait()
	return appendResults(results)
}

func appendResults(rs []Result) error {
	var all []Result
	b, err := os.ReadFile(resultsPath)
	switch {
	case err == nil:
		if err := json.Unmarshal(b, &all); err != nil {
			return fmt.Errorf("parse %s: %w", resultsPath, err)
		}
	case !os.IsNotExist(err):
		return fmt.Errorf("read %s: %w", resultsPath, err)
	}
	all = append(all, rs...)
	b, err = json.Marshal(all)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(resultsPath), 0o755); err != nil {
		return err
	}
	// Write to a temp file and rename so a crash never leaves a truncated results.json.
	tmp := resultsPath + ".tmp"
	if err := os.WriteFile(tmp, b, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, resultsPath)
}

